public class Main {
    static final int MOD = 1_000_000_007;
    static String[] words;
    static int n;
    static int[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = sc.next();
        }
        sc.close();

        memo = new int[n][];
        for (int i = 0; i < n - 1; i++) {
            memo[i] = new int[words[i].length() + 1];
            Arrays.fill(memo[i], -1);
        }

        long ans = 1;
        for (int i = 0; i < n - 1; i++) {
            ans = ans * solve(i, 0) % MOD;
        }
        System.out.println(ans);
    }

    static int solve(int idx, int pos) {
        String a = words[idx];
        String b = words[idx + 1];
        int lenA = a.length();
        int lenB = b.length();

        if (pos >= lenA && pos >= lenB) {
            return 1; // exactly equal so far, all remaining are same? actually if both ended, they are equal, which is invalid unless we already had a smaller char before. But if we reach here, they are equal -> invalid ordering. However we will ensure not to reach here if equal.
            // Actually if both ended and no smaller char found, order invalid -> return 0.
            return 0;
        }
        if (pos >= lenA) {
            // a ended, b still has chars -> a < b automatically (empty prefix is smaller)
            return 1;
        }
        if (pos >= lenB) {
            // b ended but a still has chars -> a > b, invalid
            return 0;
        }

        if (memo[idx][pos] != -1) return memo[idx][pos];

        char ca = a.charAt(pos);
        char cb = b.charAt(pos);
        long res = 0;

        if (ca != '?' && cb != '?') {
            if (ca < cb) {
                res = 1;
            } else if (ca == cb) {
                res = solve(idx, pos + 1);
            } else {
                res = 0;
            }
        } else if (ca == '?' && cb == '?') {
            // 26*26 combos:
            // ca < cb: 26*25/2 = 325 ways
            // ca == cb: 26 ways, then continue
            res = (325L * modPow(26, countRemaining(a, pos+1) + countRemaining(b, pos+1))) % MOD;
            res = (res + 26L * solve(idx, pos + 1)) % MOD;
        } else if (ca == '?') {
            // cb fixed
            // ca < cb: cb - 'a' ways
            // ca == cb: 1 way, continue
            int cbVal = cb - 'a';
            long waysLess = cbVal;
            res = (waysLess * modPow(26, countRemaining(a, pos+1))) % MOD;
            res = (res + solve(idx, pos + 1)) % MOD; // ca == cb
        } else {
            // cb == '?', ca fixed
            int caVal = ca - 'a';
            long waysMore = 25 - caVal; // ca < cb
            res = (waysMore * modPow(26, countRemaining(b, pos+1))) % MOD;
            res = (res + solve(idx, pos + 1)) % MOD; // ca == cb
        }

        memo[idx][pos] = (int) res;
        return (int) res;
    }

    static int countRemaining(String s, int start) {
        int cnt = 0;
        for (int i = start; i < s.length(); i++) {
            if (s.charAt(i) == '?') cnt++;
        }
        return cnt;
    }

    static long modPow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }
}

