    // Count number of ways to replace ? in a,b so that a < b lexicographically.
    static long countLessWays(String a, String b) {
        int la = a.length(), lb = b.length();
        int maxL = Math.max(la, lb);

        // dpEqual: number of ways prefixes are equal so far
        // dpLess : number of ways already decided a < b earlier
        long dpEqual = 1;
        long dpLess = 0;

        for (int i = 0; i < maxL; i++) {
            long nextEqual = 0;
            long nextLess = 0;

            boolean enda = (i >= la);
            boolean endb = (i >= lb);

            if (enda && endb) {
                // both ended: equal remains equal
                nextEqual = dpEqual;
                nextLess = dpLess;
            } else if (enda) {
                // a ended, b not ended => if equal so far, then a < b
                nextLess = (dpLess + dpEqual) % MOD;
            } else if (endb) {
                // b ended, a not ended => equal so far cannot continue to valid a < b
                nextLess = dpLess;
            } else {
                char ca = a.charAt(i);
                char cb = b.charAt(i);

                long eqWays = countEq(ca, cb);
                long lessWays = countLess(ca, cb);
