            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import sys
from itertools import product

def solve():
    MOD = 1_000_000_007
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    words = input_data[1:n+1]

    def completions(w):
        q = w.count('?')
        results = []
        for combo in product(range(26), repeat=q):
            res = list(w)
            j = 0
            for i in range(len(res)):
                if res[i] == '?':
                    res[i] = chr(ord('a') + combo[j])
                    j += 1
            results.append(''.join(res))
        return results

    prev_completions = {}
    for c in completions(words[0]):
        prev_completions[c] = prev_completions.get(c, 0) + 1

    for i in range(1, n):
        curr_completions = completions(words[i])
        new_prev = {}
        for cb in curr_completions:
            total = 0
            for ca, cnt in prev_completions.items():
                if ca < cb:
                    total = (total + cnt) % MOD
            if total > 0:
                new_prev[cb] = (new_prev.get(cb, 0) + total) % MOD
        prev_completions = new_prev

    print(sum(prev_completions.values()) % MOD)

solve()

import sys

MOD = 10**9 + 7
ALPHA = 26

def add_edge(g, indeg, u, v):
    if u == v:
        return
    if v not in g[u]:
        g[u].add(v)
        indeg[v] += 1

def count_topo_orders(edges_mask, present_mask):
    # Count linear extensions of a DAG on the set of letters in present_mask
    # vertices are 0..25
    verts = [i for i in range(ALPHA) if (present_mask >> i) & 1]
    k = len(verts)
    if k <= 1:
        return 1

    idx = {v: i for i, v in enumerate(verts)}
    pre = [0] * k
    for u in verts:
        mask = edges_mask[u]
        iu = idx[u]
        m = mask
        while m:
            b = (m & -m).bit_length() - 1
            if b in idx:
                pre[idx[b]] |= 1 << iu
            m &= m - 1

    size = 1 << k
    dp = [0] * size
    dp[0] = 1
    for s in range(size):
        cur = dp[s]
        if cur == 0:
            continue
        for i in range(k):
            if (s >> i) & 1:
                continue
            if pre[i] & ~s:
                continue
            ns = s | (1 << i)
            dp[ns] += cur
            if dp[ns] >= MOD:
                dp[ns] -= MOD
    return dp[-1]

def main():
    input = sys.stdin.readline
    n = int(input())
    s = [input().strip() for _ in range(n)]

    # Build graph constraints between letters:
    # if at first differing position between adjacent words we have x and y,
    # then x < y in the unknown alphabet order.
    g = [set() for _ in range(ALPHA)]
    indeg = [0] * ALPHA
    present_mask = 0

    # all letters appearing are "present"
    for w in s:
        for ch in w:
            c = ord(ch) - 97
            present_mask |= 1 << c

    possible = True

    for i in range(n - 1):
        a = s[i]
        b = s[i + 1]
        la, lb = len(a), len(b)
        m = min(la, lb)
        pos = 0
        while pos < m and a[pos] == b[pos]:
            pos += 1
        if pos == m:
            if la >= lb:
                possible = False
                break
        else:
            u = ord(a[pos]) - 97
            v = ord(b[pos]) - 97
            add_edge(g, indeg, u, v)

    if not possible:
        print(0)
        return

    # Detect cycle and also prepare bitmasks
    from collections import deque
    q = deque()
    indeg2 = indeg[:]
    for i in range(ALPHA):
        if (present_mask >> i) & 1 and indeg2[i] == 0:
            q.append(i)

    cnt = 0
    topo = []
    while q:
        v = q.popleft()
        topo.append(v)
        cnt += 1
        for to in g[v]:
            indeg2[to] -= 1
            if indeg2[to] == 0:
                q.append(to)

    if cnt != bin(present_mask).count("1"):
        print(0)
        return

    edges_mask = [0] * ALPHA
    for u in range(ALPHA):
        mask = 0
        for v in g[u]:
            mask |= 1 << v
        edges_mask[u] = mask

    ans = count_topo_orders(edges_mask, present_mask)
    print(ans % MOD)

if __name__ == "__main__":
    main()
